CREATE TABLE `velix_media_rights` (`id` text PRIMARY KEY NOT NULL, `project_id` text NOT NULL REFERENCES `video_projects`(`id`) ON DELETE CASCADE, `reference_id` text NOT NULL REFERENCES `velix_media_references`(`id`) ON DELETE CASCADE, `owner` text NOT NULL, `source_url` text NOT NULL, `license` text NOT NULL, `evidence` text, `verified_at` text, `credit` text, `restrictions` text NOT NULL DEFAULT '[]', `status` text NOT NULL, `created_at` text NOT NULL DEFAULT (datetime('now')));
